from boltons.setutils import IndexedSet
import random
for trial in range(200):
    n = random.randint(0, 12)
    x = IndexedSet(range(n))
    for _ in range(random.randint(0, n)):
        if x: x.discard(random.randrange(n))
    fresh = IndexedSet(x)
    ref = list(x)
    for i in list(range(-n-2, n+3)) + [None]:
        for j in list(range(-n-2, n+3)) + [None]:
            for k in [None, 1, 2, 3, -1, -2, -3]:
                s = slice(i, j, k)
                assert list(x[s]) == list(fresh[s]), (n, x, s)
                if k is None or k > 0:
                    assert list(x[s]) == ref[s], (n, x, s)
    for i in range(-n, n):
        assert x[i] == ref[i % n] if ref else True
print('ok')
