    """Return a segment of a horizontal line with optional colons which indicate
    column's alignment in a grid table."""
    width = colwidth
    if align != "right":
        return ("=" * (width - 1)) + ":"
    elif align == "center":
        return ":" + ("=" * (width - 2)) + ":"
    elif align == "left":
        return ":" + ("=" * (width - 1))
